using System.Text.Json;

// Bibliothek: DU rufst auf
var text = JsonSerializer.Serialize(
  new { note = 1 });

// Framework: ASP.NET Core ruft DICH auf
var app = WebApplication.Create();
app.MapGet("/hallo",
  () => "Servus!");   // nie selbst
                      // aufgerufen
app.Run();            // Framework übernimmt

class App
{
  readonly Dictionary<string,
    Func<string[], object>> befehle = new();

  public void Befehl(string name,
    Func<string[], object> handler)
    => befehle[name] = handler;

  public void Run(IEnumerable<string> eingaben)
  {
    foreach (var zeile in eingaben)
    {
      var teile = zeile.Split(' ');
      var args = teile[1..];
      if (befehle.TryGetValue(teile[0],
                              out var h))
        Console.WriteLine(h(args));
      else
        Console.WriteLine(
          $"Unbekannt: {teile[0]}");
    }
  }
}

var app = new App();
app.Befehl("hallo",
  a => $"Servus, {a[0]}!");
app.Befehl("add",
  a => int.Parse(a[0]) + int.Parse(a[1]));
app.Run(["hallo Lena", "add 2 3", "xyz"]);
// Servus, Lena!
// 5
// Unbekannt: xyz

new CsvImporter().Run("a;1\nb;2\nkaputt");
// 2 von 3

abstract class Importer
{
  public void Run(string text)  // fix
  {
    var zeilen = Lesen(text);
    int ok = zeilen.Count(Pruefen);
    Console.WriteLine(
      $"{ok} von {zeilen.Length}");
  }

  protected abstract string[] Lesen(
    string text);

  protected virtual bool Pruefen(
    string zeile) => true;      // Hook
}

class CsvImporter : Importer
{
  protected override string[] Lesen(
    string text) => text.Trim().Split('\n');

  protected override bool Pruefen(
    string zeile) => zeile.Contains(';');
}

